local _, addon = ...
addon.localeData.frFR.texts = {
    POWER_WORD_FORTITUDE = { gruppe = { "Tiens-toi droit. Ton courage survivra au doute.", "Le courage ne se donne pas. Mais on peut l'affermir.", "*trace devant sa poitrine un signe de Lumière inébranlable.*", "*pose une main sur l'épaule tandis qu'une rune dorée s'illumine.*" }, ziel = { "Tiens-toi droit. Ton courage survivra au doute.", "%s, que votre force tienne quand vos jambes faibliront.", "*trace devant sa poitrine un signe de Lumière inébranlable.*", "*pose une main sur l'épaule tandis qu'une rune dorée s'illumine.*" }, },
    POWER_WORD_SHIELD = { gruppe = { "Parfois, un instant de sûreté est le plus grand miracle.", "Un autre coup peut venir. Cette Lumière lui fera face.", "*pose deux doigts sur son poignet et dresse une barrière dorée.*", "*éprouve la protection scintillante d'un geste calme.*" }, ziel = { "Parfois, un instant de sûreté est le plus grand miracle.", "%s, cette protection vous donne l'instant nécessaire.", "*pose deux doigts sur son poignet et dresse une barrière dorée.*", "*éprouve la protection scintillante d'un geste calme.*" }, },
    CONFOUNDING_FLASH = { gruppe = { "Une étincelle de confusion peut être la réponse la plus sage.", "Un instant d'éblouissement suffit à défaire tout un plan.", "*projette un point de Lumière vacillant qui brouille brièvement la vue.*", "*penche la tête comme pour étudier l'effet de l'éclair soudain.*" }, },
    STARSHARDS = { gruppe = { "Les étoiles se sont tues assez longtemps. Elles répondent enfin.", "Ce qui brille loin dans le ciel peut frapper durement ici-bas.", "*dessine une constellation et en extrait des éclats scintillants.*", "*tend la main tandis que de petites lumières descendent en arc.*" }, ziel = { "Les étoiles se sont tues assez longtemps. Elles répondent enfin.", "%s, même les étoiles lointaines vous ont remarqué.", "*dessine une constellation et en extrait des éclats scintillants.*", "*tend la main tandis que de petites lumières descendent en arc.*" }, },
    INNER_FIRE = { gruppe = { "Une petite flamme suffit à défier tout un hiver.", "La braise en moi n'a besoin ni de bois ni de vent.", "*pose les deux paumes sur sa poitrine jusqu'à ce que la robe rayonne de chaleur.*", "*trace un petit cercle de flammes près de son corps.*" }, },
    DISPEL_MAGIC = { gruppe = { "Magie étrangère, ton heure est venue.", "Tous les enchantements étrangers n'ont pas leur place en ce monde.", "*saisit un fil invisible et le défait de la trame magique.*", "*balaye les dernières étincelles étrangères de sa paume ouverte.*" }, },
    CONTINGENCY_PLAN = { gruppe = { "Je crois en la Lumière, mais je prépare le pire.", "Prévoir le pire ne revient pas à douter de la Lumière. C'est veiller sur autrui.", "*superpose deux signes lumineux, dont l'un reste dissimulé.*", "*vérifie le sceau discret posé sur l'épaule de son compagnon.*" }, ziel = { "Je crois en la Lumière, mais je prépare le pire.", "%s, si tout tourne mal, que cette bénédiction vous retienne.", "*superpose deux signes lumineux, dont l'un reste dissimulé.*", "*vérifie le sceau discret posé sur l'épaule de son compagnon.*" }, },
    ELUNES_GRACE = { gruppe = { "Élune, laisse-moi glisser entre les coups.", "Entre deux battements de cœur, la lune m'accorde un pas sûr.", "*trace un croissant et glisse sur le côté pour éviter le coup.*", "*baisse les yeux tandis qu'une lueur argentée effleure sa silhouette.*" }, },
    FEEDBACK = { gruppe = { "Touche mes pensées, tu trouveras un miroir d'épines.", "Quiconque ébranle mon esprit risque de réveiller ses propres doutes.", "*resserre un voile scintillant autour de ses tempes.*", "*fait briller de petites épines de Lumière qui se reflètent vers l'intérieur.*" }, },
    SHACKLE_UNDEAD = { gruppe = { "Silence, âme perdue. Ton voyage s'arrête ici un instant.", "La mort ne vous a pas libéré. Ma magie non plus, pour l'instant.", "*enroule un ruban pâle de Lumière autour d'une silhouette invisible.*", "*maintient la paume immobile tandis que le sceau se resserre.*" }, ziel = { "Silence, âme perdue. Ton voyage s'arrête ici un instant.", "%s, restez ici. Les vivants doivent passer.", "*enroule un ruban pâle de Lumière autour d'une silhouette invisible.*", "*maintient la paume immobile tandis que le sceau se resserre.*" }, },
    MANA_BURN = { gruppe = { "Ta magie crépite si fort que je la plaindrais presque.", "Vous avez laissé votre pouvoir à découvert. J'en retire simplement l'excès.", "*referme les doigts comme pour éteindre une flamme invisible.*", "*arrache une étincelle brûlante à la trame magique de l'ennemi.*" }, ziel = { "Ta magie crépite si fort que je la plaindrais presque.", "%s, votre magie se fatiguera avant votre orgueil.", "*referme les doigts comme pour éteindre une flamme invisible.*", "*arrache une étincelle brûlante à la trame magique de l'ennemi.*" }, },
    DIVINE_SPIRIT = { gruppe = { "Tes pensées n'ont pas besoin de cage, seulement d'une ancre.", "La clarté naît quand nous laissons moins de place au tumulte.", "*touche son front de deux doigts et guide un fil lumineux vers son allié.*", "*ouvre les mains comme pour diffuser une pensée paisible.*" }, ziel = { "Tes pensées n'ont pas besoin de cage, seulement d'une ancre.", "%s, gardez l'esprit clair même quand le monde gronde.", "*touche son front de deux doigts et guide un fil lumineux vers son allié.*", "*ouvre les mains comme pour diffuser une pensée paisible.*" }, },
    PENANCE = { gruppe = { "Un jugement peut être blessure et pansement à la fois.", "Trois instants suffisent : comprendre, agir et espérer à nouveau.", "*déplace la main en arcs brefs et précis dans un rayon de Lumière.*", "*s'immobilise tandis que la dernière lueur s'efface de sa paume.*" }, },
    LEVITATE = { gruppe = { "Le sol pourra me reprendre plus tard.", "Les soucis semblent si petits dès que les pieds quittent le sol.", "*soulève les talons tandis qu'une fine poussière flotte sous ses bottes.*", "*écarte les bras et s'élève d'un doigt au-dessus de la terre.*" }, },
    PRAYER_OF_FORTITUDE = { gruppe = { "Qu'aucun de nous ne perde courage aujourd'hui.", "Notre force grandit quand personne n'affronte seul le prochain pas.", "*écarte les bras tandis que plusieurs sceaux dorés s'illuminent.*", "*incline la tête pendant que la bénédiction passe d'un compagnon à l'autre.*" }, },
    PRAYER_OF_SPIRIT = { gruppe = { "Nous respirons séparément, mais espérons ensemble.", "Que nos pensées diffèrent, mais que notre espoir soit partagé.", "*relie plusieurs points de Lumière d'un geste calme.*", "*écoute un battement de cœur tandis qu'une douce bénédiction gagne le groupe.*" }, },
    INNER_FOCUS = { gruppe = { "Toutes les voix se taisent. Une seule volonté demeure.", "Ni doute, ni distraction. Il ne reste que le prochain souffle.", "*ferme les yeux et joint les mains dans le calme.*", "*inspire profondément jusqu'à ce que la Lumière au bout des doigts s'apaise.*" }, },
    POWER_INFUSION = { gruppe = { "Prends cette puissance et fais-en quelque chose de bon.", "Je vous confie plus que de la force : ma confiance.", "*dirige un courant lumineux de sa main vers son allié.*", "*ouvre les doigts comme pour libérer un fil d'énergie tendu.*" }, ziel = { "Prends cette puissance et fais-en quelque chose de bon.", "%s, prenez cette force et usez-en avec sagesse.", "*dirige un courant lumineux de sa main vers son allié.*", "*ouvre les doigts comme pour libérer un fil d'énergie tendu.*" }, },
    LESSER_HEAL = { gruppe = { "Toute blessure n'exige pas un miracle, certaines demandent du temps.", "Un peu de Lumière, un peu de repos. Cela suffira pour l'instant.", "*fait glisser une étincelle chaleureuse sur une petite blessure.*", "*pose deux doigts sur le bandage et détend sa main.*" }, ziel = { "Toute blessure n'exige pas un miracle, certaines demandent du temps.", "%s, cette petite blessure ne nous arrêtera pas.", "*fait glisser une étincelle chaleureuse sur une petite blessure.*", "*pose deux doigts sur le bandage et détend sa main.*" }, },
    SMITE = { gruppe = { "La Lumière sait être douce. Pas aujourd'hui.", "Un jugement n'a pas besoin de lame quand la Lumière répond elle-même.", "*abaisse vivement la main comme si une brèche claire s'ouvrait dans le ciel.*", "*fixe le regard devant soi tandis qu'un rayon de Lumière frappe.*" }, ziel = { "La Lumière sait être douce. Pas aujourd'hui.", "%s, ce n'est pas un sermon. C'est la réponse.", "*abaisse vivement la main comme si une brèche claire s'ouvrait dans le ciel.*", "*fixe le regard devant soi tandis qu'un rayon de Lumière frappe.*" }, },
    RENEW = { gruppe = { "Guérir n'est pas un instant. C'est une promesse.", "À chaque souffle, le corps retrouve un peu de sa force.", "*tend les doigts au-dessus d'une plaie, d'où montent des points lumineux.*", "*dessine un cercle lent sur le bandage et laisse la clarté persister.*" }, ziel = { "Guérir n'est pas un instant. C'est une promesse.", "%s, la guérison se poursuit. Laissez-lui un peu de temps.", "*tend les doigts au-dessus d'une plaie, d'où montent des points lumineux.*", "*dessine un cercle lent sur le bandage et laisse la clarté persister.*" }, },
    DESPERATE_PRAYER = { gruppe = { "Quand les mots échouent, il reste une dernière prière.", "Quand mes forces me quittent, que ma foi reste ferme.", "*joint les mains et lutte pour faire naître une étincelle de Lumière.*", "*lève les yeux au ciel tandis qu'une clarté chaude enveloppe son corps.*" }, },
    DIVINE_GRACE = { gruppe = { "Pas encore. Cette vie a encore des chapitres à écrire.", "Il est encore temps de ramener une vie du bord du gouffre.", "*forme de ses deux mains un écrin protecteur de Lumière.*", "*guide doucement un fil doré vers son compagnon blessé.*" }, ziel = { "Pas encore. Cette vie a encore des chapitres à écrire.", "%s, la grâce peut encore vous atteindre. Tenez bon.", "*forme de ses deux mains un écrin protecteur de Lumière.*", "*guide doucement un fil doré vers son compagnon blessé.*" }, },
    RESURRECTION = { gruppe = { "L'histoire n'est pas finie. Tu m'entends ?", "La Lumière rejoint même ceux qui n'entendent plus nos voix.", "*s'agenouille près du corps immobile et tend doucement les mains.*", "*maintient le symbole sacré jusqu'à l'apparition d'une première lueur chaude.*" }, ziel = { "L'histoire n'est pas finie. Tu m'entends ?", "%s, revenez parmi nous. Votre place vous attend encore.", "*s'agenouille près du corps immobile et tend doucement les mains.*", "*maintient le symbole sacré jusqu'à l'apparition d'une première lueur chaude.*" }, },
    CURE_DISEASE = { gruppe = { "Ce qui s'est glissé en toi peut repartir.", "Ce qui vous affaiblit ne s'installera pas davantage.", "*touche le bandage et en retire une lueur maladive.*", "*efface d'un geste calme la dernière trace de cette clarté trouble.*" }, ziel = { "Ce qui s'est glissé en toi peut repartir.", "%s, cette maladie n'a plus sa place ici.", "*touche le bandage et en retire une lueur maladive.*", "*efface d'un geste calme la dernière trace de cette clarté trouble.*" }, },
    HEAL = { gruppe = { "Respire. Le prochain pas t'appartient.", "La peau n'est pas seule à guérir. Il faut aussi retrouver des forces.", "*pose calmement les mains près de la blessure et rassemble la Lumière.*", "*attend que la clarté chaude se répande sur le bandage.*" }, ziel = { "Respire. Le prochain pas t'appartient.", "%s, prenez ce souffle. Le suivant sera plus facile.", "*pose calmement les mains près de la blessure et rassemble la Lumière.*", "*attend que la clarté chaude se répande sur le bandage.*" }, },
    CHASTISE = { gruppe = { "Un seul mot suffit, prononcé avec conviction.", "Même au cœur de la tempête, un cœur retrouve son rythme.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, ziel = { "Un seul mot suffit, prononcé avec conviction.", "Ta prochaine pensée sera plus prudente, %s.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, },
    FEAR_WARD = { gruppe = { "Ton courage t'appartient. Je ne fais que le protéger.", "La peur peut venir. Elle ne sera pas votre maître.", "*trace un cercle ferme devant le front de son compagnon.*", "*referme la main sur un signe de Lumière qui demeure en protection.*" }, ziel = { "Ton courage t'appartient. Je ne fais que le protéger.", "%s, écoutez votre courage, pas les murmures de la peur.", "*trace un cercle ferme devant le front de son compagnon.*", "*referme la main sur un signe de Lumière qui demeure en protection.*" }, },
    FLASH_HEAL = { gruppe = { "Pas le temps de prêcher. Reste avec nous !", "Chaque seconde compte. Cette prière devra suffire.", "*tend vivement la main et libère un éclair de Lumière.*", "*reprend son souffle tandis que la guérison agit déjà.*" }, ziel = { "Pas le temps de prêcher. Reste avec nous !", "%s, restez avec moi ! La Lumière est déjà là.", "*tend vivement la main et libère un éclair de Lumière.*", "*reprend son souffle tandis que la guérison agit déjà.*" }, },
    HOLY_FIRE = { gruppe = { "Quand la Lumière brûle, aucun mensonge ne se cache.", "Ce feu ne vient d'aucune forge. Il répond à ma foi.", "*referme le poing sur une étincelle, puis la libère d'un geste.*", "*observe sans ciller la traînée de feu doré.*" }, ziel = { "Quand la Lumière brûle, aucun mensonge ne se cache.", "%s, la Lumière vous réserve aujourd'hui une réponse brûlante.", "*referme le poing sur une étincelle, puis la libère d'un geste.*", "*observe sans ciller la traînée de feu doré.*" }, },
    HOLY_NOVA = { gruppe = { "Repoussons les ténèbres ensemble.", "Une seule onde de Lumière pour que chacun reprenne souffle.", "*ouvre les bras et projette un anneau de Lumière éclatante.*", "*tourne au centre d'une vague dorée puis abaisse lentement les mains.*" }, },
    PRAYER_OF_HEALING = { gruppe = { "Un souffle d'espoir pour chacun de vous.", "Pour ceux qui tiennent encore et ceux qui peinent à rester debout.", "*lève les mains tandis que des fils de Lumière gagnent ses compagnons.*", "*incline la tête et laisse une prière commune réchauffer le groupe.*" }, },
    ABOLISH_DISEASE = { gruppe = { "Cette maladie n'a aucun droit de séjour.", "Même au cœur de la tempête, un cœur retrouve son rythme.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, ziel = { "Cette maladie n'a aucun droit de séjour.", "Tiens bon, %s. Ton histoire ne s'arrête pas ici.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, },
    GREATER_HEAL = { gruppe = { "Tiens bon. Donne-moi un instant et je t'en rendrai bien d'autres.", "Cette blessure exige plus qu'une bénédiction hâtive. Je m'y consacre entièrement.", "*affermit les bras et rassemble un large courant de Lumière dorée.*", "*garde les mains immobiles jusqu'à ce que le flot lumineux s'apaise.*" }, ziel = { "Tiens bon. Donne-moi un instant et je t'en rendrai bien d'autres.", "%s, accordez-moi cet instant. Ce soin exige toutes mes forces.", "*affermit les bras et rassemble un large courant de Lumière dorée.*", "*garde les mains immobiles jusqu'à ce que le flot lumineux s'apaise.*" }, },
    LIGHTWELL = { gruppe = { "Un endroit paisible où le courage reprend racine.", "Même au cœur de la tempête, un cœur retrouve son rythme.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, },
    LIGHTWELL_RENEW = { gruppe = { "Une goutte d'espoir peut encore se transmettre.", "Même au cœur de la tempête, un cœur retrouve son rythme.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, ziel = { "Une goutte d'espoir peut encore se transmettre.", "Tiens bon, %s. Ton histoire ne s'arrête pas ici.", "*lève les mains ouvertes en une prière muette*", "*laisse la lumière se rassembler entre ses doigts*" }, },
    PRAYER_OF_MENDING = { gruppe = { "Que ma bénédiction trouve celui qui en aura besoin.", "Cette bénédiction ne reste pas immobile. Elle cherche qui en aura besoin ensuite.", "*fait voyager une petite sphère de Lumière parmi ses compagnons.*", "*tend deux doigts pour guider la bénédiction scintillante plus loin.*" }, ziel = { "Que ma bénédiction trouve celui qui en aura besoin.", "%s, recevez cette bénédiction. Elle en trouvera d'autres.", "*fait voyager une petite sphère de Lumière parmi ses compagnons.*", "*tend deux doigts pour guider la bénédiction scintillante plus loin.*" }, },
    SHADOW_WORD_PAIN = { gruppe = { "Un seul mot. Le reste sera ton souvenir.", "Une syllabe suffit à entourer une pensée d'épines.", "*baisse le menton tandis qu'un signe sombre se forme au-dessus de sa paume.*", "*laisse échapper un murmure rauque sans origine visible.*" }, ziel = { "Un seul mot. Le reste sera ton souvenir.", "%s, ce mot vous suivra plus longtemps que vous ne le souhaitez.", "*baisse le menton tandis qu'un signe sombre se forme au-dessus de sa paume.*", "*laisse échapper un murmure rauque sans origine visible.*" }, },
    FADE = { gruppe = { "Nul besoin de disparaître pour passer inaperçu.", "Un pas hors des regards suffit. Les ombres font le reste.", "*ramène l'ombre de sa cape sur ses épaules tel un voile.*", "*baisse les yeux et semble disparaître dans la foule.*" }, },
    HEX_OF_WEAKNESS = { gruppe = { "La force est une histoire qu'on t'a trop racontée.", "Une malédiction n'a besoin d'aucune lame pour ôter la force.", "*tisse trois signes obscurs en un ruban étroit.*", "*ouvre la main et libère une rune tremblante.*" }, ziel = { "La force est une histoire qu'on t'a trop racontée.", "%s, votre force vient de payer un prix inattendu.", "*tisse trois signes obscurs en un ruban étroit.*", "*ouvre la main et libère une rune tremblante.*" }, },
    MIND_BLAST = { gruppe = { "Certaines portes doivent rester fermées. Pas celle-ci.", "Vos pensées sont une forteresse dotée d'une porte bien fragile.", "*pose deux doigts sur sa tempe avant de projeter la main en avant.*", "*fait courir une secousse invisible dans l'air.*" }, ziel = { "Certaines portes doivent rester fermées. Pas celle-ci.", "%s, vous feriez bien de retenir vos pensées.", "*pose deux doigts sur sa tempe avant de projeter la main en avant.*", "*fait courir une secousse invisible dans l'air.*" }, },
    TOUCH_OF_WEAKNESS = { gruppe = { "Derrière chaque toucher se cache une autre intention.", "Cette main ne porte aucune arme. Elle n'est pas inoffensive pour autant.", "*observe une ombre terne glisser le long de ses doigts.*", "*referme lentement le poing en laissant une trace obscure.*" }, },
    PSYCHIC_SCREAM = { gruppe = { "La peur a une voix. Je lui prête la mienne.", "Quand l'esprit s'enfuit, le corps n'attend plus d'ordre.", "*écarte brusquement les bras comme pour briser une chose invisible.*", "*pousse un cri muet qui fait frémir l'air.*" }, },
    DARK_SACRIFICE = { gruppe = { "Un prix doit être payé. Aujourd'hui, je connais le débiteur.", "Le pouvoir exige son tribut. Je connais le prix.", "*trace un signe noir dans sa paume.*", "*ferme les yeux tandis qu'une lueur sombre vacille brièvement.*" }, },
    DEVOURING_PLAGUE = { gruppe = { "Ton orgueil a des racines. Je vais les arracher.", "Certaines corruptions naissent d'un seul souffle imprudent.", "*rassemble un voile maladif de vapeur obscure.*", "*abaisse la main tandis qu'une brume verdâtre s'éloigne.*" }, ziel = { "Ton orgueil a des racines. Je vais les arracher.", "%s, même votre orgueil ne vous protégera pas de ce fléau.", "*rassemble un voile maladif de vapeur obscure.*", "*abaisse la main tandis qu'une brume verdâtre s'éloigne.*" }, },
    MIND_FLAY = { gruppe = { "L'esprit est une étoffe fragile. Entends-tu la déchirure ?", "Une pensée après l'autre. Je vais les séparer avec soin.", "*pose deux doigts sur sa tempe et tire un fil violet dans l'air.*", "*plisse les yeux tandis qu'un mince rayon d'ombre palpite.*" }, ziel = { "L'esprit est une étoffe fragile. Entends-tu la déchirure ?", "%s, vos pensées perdent leur équilibre.", "*pose deux doigts sur sa tempe et tire un fil violet dans l'air.*", "*plisse les yeux tandis qu'un mince rayon d'ombre palpite.*" }, },
    MIND_SOOTHE = { gruppe = { "Les doutes endormis sont les meilleurs alliés.", "Un esprit apaisé pose moins de questions. Cela nous arrange.", "*abaisse lentement la paume comme pour lisser une vague invisible.*", "*expire sans bruit tandis que l'agitation alentour s'apaise.*" }, ziel = { "Les doutes endormis sont les meilleurs alliés.", "%s, un peu de calme vous fera du bien à présent.", "*abaisse lentement la paume comme pour lisser une vague invisible.*", "*expire sans bruit tandis que l'agitation alentour s'apaise.*" }, },
    SHADOWGUARD = { gruppe = { "Je porte mes ténèbres avec dignité. Et des épines.", "Frappez donc. Les ombres oublient rarement qui les réveille.", "*fait tourner des étincelles sombres autour de son corps.*", "*tourne la paume vers l'extérieur tandis qu'un voile protecteur s'illumine.*" }, },
    MIND_VISION = { gruppe = { "Tes yeux me montreront ce que tu ne vois pas.", "La distance ne protège pas vos secrets de mon regard.", "*porte les doigts aux yeux et observe à travers une ombre lointaine.*", "*fixe le vide tandis que sa conscience voyage ailleurs.*" }, ziel = { "Tes yeux me montreront ce que tu ne vois pas.", "%s, j'aperçois désormais une partie de votre monde.", "*porte les doigts aux yeux et observe à travers une ombre lointaine.*", "*fixe le vide tandis que sa conscience voyage ailleurs.*" }, },
    MIND_CONTROL = { gruppe = { "Pour un instant, ton choix sera le mien.", "Une seule pensée empruntée, et le chemin change.", "*tire lentement un fil invisible entre le pouce et l'index.*", "*incline la tête tandis qu'un signe obscur apparaît au-dessus du front.*" }, ziel = { "Pour un instant, ton choix sera le mien.", "%s, pour un instant, vous suivrez la voie que je trace.", "*tire lentement un fil invisible entre le pouce et l'index.*", "*incline la tête tandis qu'un signe obscur apparaît au-dessus du front.*" }, },
    SHADOW_PROTECTION = { gruppe = { "Je connais la nuit. C'est pourquoi je ne la crains pas.", "Les ténèbres ont bien des chemins. Cette protection en ferme un.", "*enveloppe son allié d'un voile violet et silencieux.*", "*éprouve le cercle protecteur sombre d'un lent mouvement de la main.*" }, ziel = { "Je connais la nuit. C'est pourquoi je ne la crains pas.", "%s, que cette ombre vous préserve des autres.", "*enveloppe son allié d'un voile violet et silencieux.*", "*éprouve le cercle protecteur sombre d'un lent mouvement de la main.*" }, },
    SHADOW_WORD_DEATH = { gruppe = { "Voici le mot qu'on ne peut reprendre.", "Un dernier mot pèse plus lourd que toutes les menaces précédentes.", "*forme une fine rune noire entre deux doigts.*", "*abaisse la main tandis qu'une impulsion sombre s'élance.*" }, ziel = { "Voici le mot qu'on ne peut reprendre.", "%s, je ne prononce pas ce mot à la légère.", "*forme une fine rune noire entre deux doigts.*", "*abaisse la main tandis qu'une impulsion sombre s'élance.*" }, },
    PRAYER_OF_SHADOW_PROTECTION = { gruppe = { "Nous traversons les ténèbres sans nous y perdre.", "Nous restons unis, même quand la Lumière semble lointaine.", "*lève les mains tandis que des sceaux sombres entourent le groupe.*", "*incline la tête et relie plusieurs anneaux protecteurs violets.*" }, },
    VAMPIRIC_EMBRACE = { gruppe = { "Étrange comme la douleur et le réconfort se côtoient.", "Même les ténèbres peuvent réconforter. Leur prix reste amer.", "*tire un fil sombre de l'air et le laisse devenir une douce lumière.*", "*ouvre les bras tandis qu'une lueur violette effleure les alliés.*" }, ziel = { "Étrange comme la douleur et le réconfort se côtoient.", "%s, même ces ténèbres peuvent rendre des forces aux vivants.", "*tire un fil sombre de l'air et le laisse devenir une douce lumière.*", "*ouvre les bras tandis qu'une lueur violette effleure les alliés.*" }, },
    SILENCE = { gruppe = { "Il est des réponses qu'on ne trouve que dans le silence.", "Aucun sort ne commence sans son premier mot.", "*pose un doigt sur ses lèvres et fait taire l'air alentour.*", "*referme le poing tandis qu'un son scintillant s'y éteint.*" }, ziel = { "Il est des réponses qu'on ne trouve que dans le silence.", "%s, gardez votre prochaine incantation pour vous un instant.", "*pose un doigt sur ses lèvres et fait taire l'air alentour.*", "*referme le poing tandis qu'un son scintillant s'y éteint.*" }, },
    SHADOWFORM = { gruppe = { "Rien en moi ne s'est éteint. La lumière tombe autrement.", "Je porte l'ombre, mais je refuse qu'elle me porte.", "*resserre sa cape tandis que sa silhouette se fond dans l'obscurité.*", "*relève lentement la tête à travers un voile de brume violette.*" }, },
    -- Freiwillige, unabhängig vom Zauberbuch nutzbare Priester-RP-Szenen
    BEDSIDE_PRAYER = { gruppe = { "Toute guérison ne commence pas par la magie. Certaines commencent par l'écoute.", "Même le souffle le plus faible mérite notre attention entière.", "*pose un bol d'eau près de la couche et vérifie le pouls d'un blessé.*", "*prononce une prière discrète sans retirer sa main de l'épaule.*" }, ziel = { "%s, je resterai aussi longtemps que tu auras besoin de moi." }, },
    SHRINE_VIGIL = { gruppe = { "Ce soir, le sanctuaire contient plus de questions que de réponses.", "L'espoir est peut-être le courage de revenir demain.", "*allume une petite bougie et protège la flamme du vent.*", "*s'agenouille et garde le silence un moment.*" }, },
    CONFESSION = { gruppe = { "Je t'écoute. Personne ici ne juge à la légère.", "Nous ne pouvons pas toujours changer la vérité, mais choisir le prochain pas.", "*s'assied tranquillement et pose son bâton de côté.*", "*hoche lentement la tête et laisse à l'autre le temps de parler.*" }, ziel = { "%s, dis-moi ce qui pèse sur ton cœur." }, },
    LAST_RITES = { gruppe = { "Un nom demeure même lorsque la voix s'est tue.", "Que la route au-delà de notre regard soit paisible.", "*recouvre doucement la dépouille d'une couverture.*", "*baisse la tête et bénit ceux qui restent.*" }, ziel = { "Ton nom ne sera pas oublié, %s." }, },
    MEDITATION = { gruppe = { "Le silence n'est pas un vase vide.", "Une bonne pensée réclame un espace entre deux souffles.", "*s'assied bien droit, les mains posées sur les genoux.*", "*ferme les yeux et compte lentement ses respirations.*" }, },
